import json, os, re, shutil

ROOT=Path(__file__).resolve().parents[1]
M=json.loads((ROOT/'sources/reader-manifest.json').read_text())

def write(path,text):
 p=ROOT/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text.strip()+'\n')
def target(label,from_path='docs/research/index.md'):
 path,anchor=M['targets'][label]
 return os.path.relpath(ROOT/path,(ROOT/from_path).parent)+'#'+anchor
def b(n,label):return f'[{label}](../bibliography/entries/b{n:03d}.md)'

